def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    change_ratio = (new - old) / old
    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_net_sales": old,
            "new_net_sales": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
